package com.hotel.service.impl; import com.hotel.dao.RoomDao; import com.hotel.dto.AvailableRoomDto; import com.hotel.service.RoomAvailabilityService; import java.util.*; public class RoomAvailabilityServiceImpl implements RoomAvailabilityService{private final RoomDao dao;public RoomAvailabilityServiceImpl(RoomDao dao){this.dao=dao;}public Optional<List<AvailableRoomDto>> find(long id,Integer floor){if(id<=0)return Optional.empty();return dao.findAvailable(id,floor);}}
